/**
 * Worker entry point that wraps the OpenNext-generated handler with page edge caching.
 * See src/edge/page-cache.ts for caching logic.
 * The scheduled cron triggers ingest and refreshes stale city snapshots.
 */

// @ts-expect-error .open-next/worker.js is generated by `opennextjs-cloudflare build`.
import handler from "./.open-next/worker.js";
import { withPageCache } from "./src/edge/page-cache";
import { blockedForCrawler, crawlerBlockedResponse } from "./src/edge/crawler-guard";
import { renderAllowed, rateLimitedResponse, type RateLimiter } from "./src/edge/render-limit";
import { triggerIngest } from "./src/edge/ingest-trigger";
import { canonicalRedirect } from "./src/edge/canonical-host";
import { internalToken } from "./src/edge/internal-token";

type Ctx = { waitUntil(promise: Promise<unknown>): void; passThroughOnException(): void };
interface Env {
  RENDER_LIMITER?: RateLimiter;
  INGEST_DISPATCH_TOKEN?: string;
  CF_VERSION_METADATA?: { id?: string };
  [key: string]: unknown;
}

// Cold-hit diagnosis (scaling 11-03): which request of this isolate, and first of its route kind here.
let isolateStart = 0; // set on the first request: Date.now() is 0 at module scope on Workers
let isolateRequests = 0;
const routeKindsSeen = new Set<string>();
const routeKind = (pathname: string): string =>
  pathname === "/"
    ? "home"
    : pathname.startsWith("/e/")
      ? "event"
      : pathname.startsWith("/_next/")
        ? "next"
        : pathname.split("/").length === 2
          ? "city"
          : "other";

export default {
  async fetch(request: Request, env: Env, ctx: Ctx): Promise<Response> {
    // www and the .app hosts 301 to https://dancetonightglobal.com, same path and query
    const redirect = canonicalRedirect(request);
    if (redirect !== null) return redirect;

    // Block crawlers that request URLs with query strings (disallowed by robots.txt)
    if (blockedForCrawler(request)) return crawlerBlockedResponse();

    if (isolateStart === 0) isolateStart = Date.now();
    const n = ++isolateRequests;
    const kind = routeKind(new URL(request.url).pathname);
    const firstOfKind = !routeKindsSeen.has(kind);
    routeKindsSeen.add(kind);

    const cache = (caches as unknown as { default: Cache }).default;
    const response = await withPageCache(
      request,
      async (r) =>
        (await renderAllowed(r, env.RENDER_LIMITER))
          ? handler.fetch(r, env, ctx)
          : rateLimitedResponse(),
      cache,
      (p) => ctx.waitUntil(p),
      Date.now,
      env.CF_VERSION_METADATA?.id ?? "",
    );
    try {
      const timed = new Response(response.body, response);
      timed.headers.append(
        "server-timing",
        `isolate;desc="n=${n} age=${Math.round((Date.now() - isolateStart) / 1000)}s kind=${kind} first=${firstOfKind ? 1 : 0}"`,
      );
      return timed;
    } catch {
      return response;
    }
  },
  async scheduled(controller: { scheduledTime: number }, env: Env, ctx: Ctx): Promise<void> {
    ctx.waitUntil(
      triggerIngest(new Date(controller.scheduledTime), env.INGEST_DISPATCH_TOKEN).then((note) =>
        console.log(note),
      ),
    );
    ctx.waitUntil(
      handler
        .fetch(
          new Request("https://dancetonightglobal.com/internal/snapshots", {
            method: "POST",
            headers: { "x-dt-internal": internalToken() },
          }),
          env,
          ctx,
        )
        .then((r: Response) => r.text())
        .then((t: string) => console.log(`snapshots ${t}`))
        .catch((e: unknown) => console.log(`snapshots failed: ${String(e)}`)),
    );
  },
};
